import type { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import type { Options as ZagToastOptions, StoreProps as ToastStoreProps } from "@zag-js/toast";

export type ToastMeta = {
  icon?: IconDefinition;
  iconStart?: boolean;
};

export type ShowToastOptions = Omit<ZagToastOptions, "type" | "meta"> & {
  type: "error" | "info" | "success" | "warning";
  meta?: ToastMeta;
} & Partial<ToastStoreProps>;

export type ShowToastFn = (options: ShowToastOptions) => void;

export type UpdateToastOptions = Partial<ShowToastOptions>;

export type UpdateToastFn = (id: string, options: UpdateToastOptions) => void;

export type DismissToastFn = (id: string) => void;

export type IsToastVisibleFn = (id: string) => boolean;
